87	// ParseAnthropic decodes Anthropic Messages-API rate-limit headers.
88	//
89	// Recognized canonical headers (current Anthropic docs):
90	//
91	//	anthropic-ratelimit-requests-{limit,remaining,reset}
92	//	anthropic-ratelimit-tokens-{limit,remaining,reset}
93	//	anthropic-ratelimit-input-tokens-{limit,remaining,reset}
94	//	anthropic-ratelimit-output-tokens-{limit,remaining,reset}
95	//	retry-after
96	//
97	// The bead also references the legacy "X-RateLimit-Remaining-*" family;
98	// those names are accepted for forward-compatibility but the canonical
99	// "anthropic-ratelimit-*" names are preferred when both are present.
100	//
101	// Reset values are RFC3339 timestamps (Anthropic) and are returned as the
102	// minimum of the per-axis reset times so the consumer wakes at the earliest
103	// recovery boundary.
104	func ParseAnthropic(h http.Header, now time.Time) Signal {
105		if h == nil {
106			return Signal{RemainingTokens: -1, RemainingRequests: -1}
107		}
108		sig := Signal{RemainingTokens: -1, RemainingRequests: -1}
109	
110		requestsRem, requestsRemOK := readInt(h, "anthropic-ratelimit-requests-remaining", "x-ratelimit-remaining-requests")
111		if requestsRemOK {
112			sig.Present = true
113			sig.RemainingRequests = requestsRem
114		}
115	
116		// Anthropic exposes total-tokens, plus per-axis input/output budgets.
117		// Track the smallest reported "remaining tokens" since the smallest
118		// budget is the binding one for the next request.
119		tokenAxes := []string{
120			"anthropic-ratelimit-tokens-remaining",
121			"anthropic-ratelimit-input-tokens-remaining",
122			"anthropic-ratelimit-output-tokens-remaining",
123			"x-ratelimit-remaining-tokens",
124		}
125		for _, name := range tokenAxes {
126			v, ok := readInt(h, name)
127			if !ok {
128				continue
129			}
130			sig.Present = true
131			if sig.RemainingTokens < 0 || v < sig.RemainingTokens {
132				sig.RemainingTokens = v
133			}
134		}
135	
136		resetAxes := []string{
137			"anthropic-ratelimit-requests-reset",
138			"anthropic-ratelimit-tokens-reset",
139			"anthropic-ratelimit-input-tokens-reset",
140			"anthropic-ratelimit-output-tokens-reset",
141		}
142		for _, name := range resetAxes {
143			raw := strings.TrimSpace(h.Get(name))
144			if raw == "" {
145				continue
146			}
147			t, err := time.Parse(time.RFC3339, raw)
148			if err != nil {
149				continue
150			}
151			sig.Present = true
152			if sig.ResetTime.IsZero() || t.Before(sig.ResetTime) {
153				sig.ResetTime = t
154			}
155		}
156	
157		if d, ok := readRetryAfter(h, now); ok {
158			sig.Present = true
159			sig.RetryAfter = d
160		}
161	
162		return sig
163	}
