1	package modelref
2	
3	import (
4		"fmt"
5		"strings"
6	)
7	
8	// ModelRef is the canonical model identity used as the cache key and routing
9	// surface: <provider>/<id>.
10	// Provider is a lowercase slug (letters, digits, hyphens, dots; no slashes).
11	// ID preserves the provider's original casing and may contain slashes
12	// (e.g. openrouter sub-paths like "qwen/qwen3.6-27b").
13	type ModelRef struct {
14		Provider string
15		ID       string
16	}
17	
18	// Parse splits s on the first "/" into Provider and ID.
19	//
20	//	"openrouter/qwen/qwen3.6-27b"  → {Provider:"openrouter", ID:"qwen/qwen3.6-27b"}
21	//	"vidar-ds4/deepseek-v4-flash"  → {Provider:"vidar-ds4", ID:"deepseek-v4-flash"}
22	func Parse(s string) (ModelRef, error) {
23		idx := strings.IndexByte(s, '/')
24		if idx < 0 {
25			return ModelRef{}, fmt.Errorf("modelref: no '/' in %q", s)
26		}
27		r := ModelRef{
28			Provider: s[:idx],
29			ID:       s[idx+1:],
30		}
31		if err := r.Validate(); err != nil {
32			return ModelRef{}, err
33		}
34		return r, nil
35	}
36	
37	// String returns "<provider>/<id>".
38	func (r ModelRef) String() string {
39		return r.Provider + "/" + r.ID
40	}
41	
42	// Validate checks that Provider and ID are non-empty and that Provider
43	// satisfies the slug rules (lowercase letters, digits, hyphens, dots; no slashes).
44	func (r ModelRef) Validate() error {
45		if r.Provider == "" {
46			return fmt.Errorf("modelref: provider is empty")
47		}
48		if r.ID == "" {
49			return fmt.Errorf("modelref: id is empty")
50		}
51		for i, c := range r.Provider {
52			if !isProviderRune(c) {
53				return fmt.Errorf("modelref: provider %q has invalid character %q at position %d", r.Provider, c, i)
54			}
55		}
56		return nil
57	}
58	
59	func isProviderRune(c rune) bool {
60		return (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '.'
61	}
