1	// Package discoverycache implements the per-source on-disk cache described in
2	// ADR-012. It provides a two-tier lock + long-lived refresh marker pattern so
3	// that slow discovery IO (PTY ~30 s, HTTP ~316 ms) never blocks UI reads.
4	//
5	// Public surface: Cache.Read, Cache.Refresh, Cache.MaybeRefresh, Cache.Prune.
6	// The Refresher function is injected; the cache manages single-flight
7	// deduplication, atomic writes, and crash recovery.
8	package discoverycache
9	
10	import (
11		"context"
12		"errors"
13		"io/fs"
14		"os"
15		"path/filepath"
16		"strings"
17		"time"
18	
19		"golang.org/x/sync/singleflight"
20	)
21	
22	const (
23		lockAcquisitionTimeout = 100 * time.Millisecond
24		lockPollInterval       = 5 * time.Millisecond
25		waitPollInterval       = 250 * time.Millisecond
26		stalenessMultiplier    = time.Duration(2)
27	)
28	
29	// Cache is the root handle. Root is the base directory (e.g. ~/.cache/fizeau).
30	// Each Cache instance owns one in-process singleflight.Group; a new Cache per
31	// process is the normal usage.
32	type Cache struct {
33		Root string
34		sf   singleflight.Group
35	}
36	
37	// Source describes one cacheable data stream (one file under Root/Tier/Name.json).
38	type Source struct {
39		// Tier is "discovery" or "runtime".
40		Tier string
41		// Name is the kebab-case source identifier (e.g. "openrouter").
42		Name string
43		// TTL controls freshness: Read returns Fresh=true when Age < TTL.
44		TTL time.Duration
45		// RefreshDeadline is the maximum time a refresh is expected to take.
46		// Also controls the staleness threshold: 2 × RefreshDeadline.
47		RefreshDeadline time.Duration
48	}
49	
50	func (s Source) key() string { return s.Tier + "/" + s.Name }
51	
52	// ReadResult is the output of Cache.Read.
53	type ReadResult struct {
54		// Data is the raw bytes from the cache file; nil if no file exists.
55		Data []byte
56		// Age is how long ago the data was written (0 if absent).
57		Age time.Duration
58		// Fresh is true when Age < TTL and Data is non-nil.
59		Fresh bool
60		// Stale is true when Data is nil or Age >= TTL.
61		Stale bool
62	}
63	
64	// Refresher is the source-fetch function injected by the caller. The cache
65	// handles single-flight deduplication, the atomic write, and marker lifecycle.
66	type Refresher func(ctx context.Context) ([]byte, error)
67	
68	// Read returns cached data without any IO beyond reading the local file.
69	// It never blocks on network or PTY. If no cache file exists, Data is nil and
70	// Stale is true. Stale data is always returned without error; the caller
71	// decides whether to trigger a background refresh.
72	func (c *Cache) Read(s Source) (ReadResult, error) {
73		path := c.dataPath(s)
74		data, err := os.ReadFile(path) // #nosec G304
75		if errors.Is(err, os.ErrNotExist) {
76			return ReadResult{Stale: true}, nil
77		}
78		if err != nil {
79			return ReadResult{}, err
80		}
81		info, err := os.Stat(path)
82		if err != nil {
83			// File was just there; best-effort fallback.
84			return ReadResult{Data: data, Stale: true}, nil
85		}
86		age := time.Since(info.ModTime())
87		if age < 0 {
88			age = 0
89		}
90		fresh := age < s.TTL
91		return ReadResult{
92			Data:  data,
93			Age:   age,
94			Fresh: fresh,
95			Stale: !fresh,
96		}, nil
97	}
98	
99	// Prune removes data files (and their sidecar lock/marker/tmp files) for
100	// sources not listed in activeSources. Sources with an active .refreshing
101	// marker are skipped. Prune acquires the tier-1 lock before removing each
102	// source's files.
103	func (c *Cache) Prune(activeSources []Source) error {
104		active := make(map[string]bool, len(activeSources))
105		for _, s := range activeSources {
106			active[s.key()] = true
107		}
108	
109		return filepath.WalkDir(c.Root, func(path string, d fs.DirEntry, err error) error {
110			if err != nil || d.IsDir() {
111				return nil
112			}
113			if !strings.HasSuffix(d.Name(), ".json") {
114				return nil
115			}
116			rel, rerr := filepath.Rel(c.Root, path)
117			if rerr != nil {
118				return nil
119			}
120			parts := strings.SplitN(rel, string(filepath.Separator), 2)
121			if len(parts) != 2 {
122				return nil
123			}
124			tier := parts[0]
125			name := strings.TrimSuffix(parts[1], ".json")
126			if strings.ContainsRune(name, filepath.Separator) {
127				return nil // nested dir, skip
128			}
129	
130			if active[tier+"/"+name] {
131				return nil
132			}
133	
134			s := Source{Tier: tier, Name: name}
135	
136			// Skip sources with an active refresh in progress.
137			m, _ := readMarker(c.markerPath(s))
138			if isMarkerActiveForPrune(m) {
139				return nil
140			}
141	
142			release, lerr := c.acquireLock(s)
143			if lerr != nil {
144				return nil // can't lock; skip this source
145			}
146			defer release()
147	
148			// Re-check under lock.
149			m2, _ := readMarker(c.markerPath(s))
150			if isMarkerActiveForPrune(m2) {
151				return nil
152			}
153	
154			_ = os.Remove(c.dataPath(s))
155			_ = os.Remove(c.markerPath(s))
156			_ = os.Remove(c.tmpPath(s))
157			return nil
158		})
159	}
