163	type claimResult struct {
164		claimed bool
165		marker  *refreshMarker
166	}
167	
168	// claimRefresh implements Algorithm 1 from ADR-012. Must be called with the
169	// source directory already created (ensured by refreshAndCommit).
170	func (c *Cache) claimRefresh(s Source) (claimResult, error) {
171		release, err := c.acquireLock(s)
172		if err != nil {
173			return claimResult{}, err
174		}
175		defer release()
176	
177		existing, _ := readMarker(c.markerPath(s))
178		if existing != nil {
179			if isStale(s, existing) {
180				_ = os.Remove(c.markerPath(s))
181			} else {
182				return claimResult{claimed: false, marker: existing}, nil
183			}
184		}
185	
186		m := &refreshMarker{
187			PID:       os.Getpid(),
188			StartedAt: time.Now().UTC(),
189			Deadline:  time.Now().UTC().Add(s.RefreshDeadline),
190		}
191		if werr := writeMarker(c.markerPath(s), m); werr != nil {
192			return claimResult{}, werr
193		}
194		return claimResult{claimed: true}, nil
195	}
196	
197	// refreshAndCommit implements Algorithm 2 from ADR-012.
198	func (c *Cache) refreshAndCommit(s Source, fn Refresher) error {
199		if err := os.MkdirAll(filepath.Join(c.Root, s.Tier), 0o750); err != nil {
200			return err
201		}
202	
203		claim, err := c.claimRefresh(s)
204		if err != nil {
205			return err
206		}
207		if !claim.claimed {
208			// Another process is refreshing; wait for it.
209			return c.waitForRefresh(s, claim.marker)
210		}
211	
212		// We hold the claim. Run slow IO outside any lock.
213		data, fetchErr := fn(context.Background())
214		if fetchErr != nil {
215			c.releaseMarker(s)
216			return fetchErr
217		}
218	
219		if werr := atomicWrite(c.dataPath(s), data); werr != nil {
220			c.releaseMarker(s)
221			return werr
222		}
223	
224		c.releaseMarker(s)
225		return nil
226	}
227	
228	// waitForRefresh implements Algorithm 3 from ADR-012. Polls until the marker
229	// disappears or becomes stale, then returns (data has been written).
230	func (c *Cache) waitForRefresh(s Source, m *refreshMarker) error {
231		// Poll until deadline + staleness_threshold or s.RefreshDeadline, whichever first.
232		threshold := s.RefreshDeadline * stalenessMultiplier
233		absoluteDeadline := m.Deadline.Add(threshold)
234		maxWait := time.Now().Add(s.RefreshDeadline)
235		if maxWait.Before(absoluteDeadline) {
236			absoluteDeadline = maxWait
237		}
238	
239		for time.Now().Before(absoluteDeadline) {
240			time.Sleep(waitPollInterval)
241			current, _ := readMarker(c.markerPath(s))
242			if current == nil || isStale(s, current) {
243				return nil
244			}
245		}
246		return nil // timed out; caller will read whatever is on disk
247	}
248	
249	// releaseMarker removes the .refreshing marker under the tier-1 lock, but
250	// only if our PID is still recorded (guard against PID-reuse races, per §2
251	// of refreshAndCommit pseudocode in ADR-012).
252	func (c *Cache) releaseMarker(s Source) {
253		release, err := c.acquireLock(s)
254		if err != nil {
255			return
256		}
257		defer release()
258		m, _ := readMarker(c.markerPath(s))
259		if m != nil && m.PID == os.Getpid() {
260			_ = os.Remove(c.markerPath(s))
261		}
262	}
263	
264	// ---- path helpers -----------------------------------------------------------
265	
266	func (c *Cache) dataPath(s Source) string {
267		return filepath.Join(c.Root, s.Tier, s.Name+".json")
268	}
269	
270	func (c *Cache) lockPath(s Source) string {
271		return filepath.Join(c.Root, s.Tier, s.Name+".lock")
272	}
273	
274	func (c *Cache) markerPath(s Source) string {
275		return filepath.Join(c.Root, s.Tier, s.Name+".refreshing")
276	}
277	
278	func (c *Cache) tmpPath(s Source) string {
279		return filepath.Join(c.Root, s.Tier, s.Name+".json.tmp")
280	}
