11	
12	type lockPayload struct {
13		PID       int       `json:"pid"`
14		StartedAt time.Time `json:"started_at"`
15	}
16	
17	// acquireLock acquires the tier-1 brief mutation lock for s. Returns a release
18	// func on success. Polls up to lockAcquisitionTimeout, recovering stale locks
19	// whose owner PID is dead (mirrors acquireMatrixLock semantics from
20	// cmd/bench/matrix.go:1222).
21	func (c *Cache) acquireLock(s Source) (func(), error) {
22		lockPath := c.lockPath(s)
23		payload := lockPayload{PID: os.Getpid(), StartedAt: time.Now().UTC()}
24		raw, _ := json.Marshal(payload)
25	
26		deadline := time.Now().Add(lockAcquisitionTimeout)
27		for {
28			f, err := os.OpenFile(lockPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600) // #nosec G304
29			if err == nil {
30				if _, werr := f.Write(raw); werr != nil {
31					_ = f.Close()
32					_ = os.Remove(lockPath)
33					return nil, werr
34				}
35				if cerr := f.Close(); cerr != nil {
36					_ = os.Remove(lockPath)
37					return nil, cerr
38				}
39				return func() { _ = os.Remove(lockPath) }, nil
40			}
41			if !errors.Is(err, os.ErrExist) {
42				return nil, err
43			}
44			// Recover stale lock if owner is dead.
45			if existing, rerr := readLockPayload(lockPath); rerr == nil && !processAlive(existing.PID) {
46				_ = os.Remove(lockPath)
47				continue
48			}
49			if time.Now().After(deadline) {
50				return nil, fmt.Errorf("discoverycache: timed out acquiring lock for %s/%s", s.Tier, s.Name)
51			}
52			time.Sleep(lockPollInterval)
53		}
54	}
55	
56	func readLockPayload(path string) (lockPayload, error) {
57		data, err := os.ReadFile(path) // #nosec G304
58		if err != nil {
59			return lockPayload{}, err
60		}
61		var p lockPayload
62		if err := json.Unmarshal(data, &p); err != nil {
63			return lockPayload{}, err
64		}
65		return p, nil
66	}
67	
68	func processAlive(pid int) bool {
69		if pid <= 0 {
70			return false
71		}
72		err := syscall.Kill(pid, 0)
73		return err == nil || errors.Is(err, syscall.EPERM)
74	}
