4		"encoding/json"
5		"errors"
6		"os"
7		"time"
8	)
9	
10	// refreshMarker is the tier-2 long-lived marker written when a refresh is
11	// in progress. Other processes inspect it to decide whether to wait or return
12	// stale data. JSON payload mirrors ADR-012 §3.
13	type refreshMarker struct {
14		PID       int       `json:"pid"`
15		StartedAt time.Time `json:"started_at"`
16		Deadline  time.Time `json:"deadline"`
17	}
18	
19	// readMarker reads the .refreshing file for s. Returns (nil, nil) if absent.
20	func readMarker(path string) (*refreshMarker, error) {
21		data, err := os.ReadFile(path) // #nosec G304
22		if errors.Is(err, os.ErrNotExist) {
23			return nil, nil
24		}
25		if err != nil {
26			return nil, err
27		}
28		var m refreshMarker
29		if err := json.Unmarshal(data, &m); err != nil {
30			// Corrupt marker — treat as absent so the caller can reclaim.
31			return nil, nil
32		}
33		return &m, nil
34	}
35	
36	// writeMarker writes m to path, overwriting any existing file.
37	func writeMarker(path string, m *refreshMarker) error {
38		data, err := json.Marshal(m)
39		if err != nil {
40			return err
41		}
42		// Overwrite (not O_EXCL) because claimRefresh already holds the tier-1 lock.
43		f, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o600) // #nosec G304
44		if err != nil {
45			return err
46		}
47		if _, werr := f.Write(data); werr != nil {
48			_ = f.Close()
49			_ = os.Remove(path)
50			return werr
51		}
52		return f.Close()
53	}
54	
55	// isStale returns true when m should be treated as an orphan.
56	// A marker is stale when: the owner PID is dead, OR now > deadline + 2×RefreshDeadline.
57	// The deadline-based check is the safety net for PID reuse (ADR-012 §3, §10 test).
58	func isStale(s Source, m *refreshMarker) bool {
59		if m == nil {
60			return true
61		}
62		if !processAlive(m.PID) {
63			return true
64		}
65		// 2× multiplier per ADR-012 "Marker staleness threshold = 2 × refresh deadline"
66		threshold := s.RefreshDeadline * stalenessMultiplier
67		return time.Now().After(m.Deadline.Add(threshold))
68	}
69	
70	// isMarkerActiveForPrune is a conservative check used only by Prune when the
71	// source's RefreshDeadline is unknown. A marker is active if its PID is alive
72	// and the deadline itself has not passed (no multiplier).
73	func isMarkerActiveForPrune(m *refreshMarker) bool {
74		if m == nil {
75			return false
76		}
77		return processAlive(m.PID) && time.Now().Before(m.Deadline)
78	}
