1261	func readMatrixLock(path string) (matrixLock, error) {
1262		data, err := os.ReadFile(path) // #nosec G304 -- path is a runner-owned lock path
1263		if err != nil {
1264			return matrixLock{}, err
1265		}
1266		var lock matrixLock
1267		if err := json.Unmarshal(data, &lock); err != nil {
1268			return matrixLock{}, err
1269		}
1270		return lock, nil
1271	}

