1	// Package discoverycache implements the per-source on-disk cache described in
2	// ADR-012. It provides a two-tier lock + long-lived refresh marker pattern so
3	// that slow discovery IO (PTY ~30 s, HTTP ~316 ms) never blocks UI reads.
4	//
5	// Public surface: Cache.Read, Cache.Refresh, Cache.MaybeRefresh, Cache.Prune.
6	// The Refresher function is injected; the cache manages single-flight
7	// deduplication, atomic writes, and crash recovery.
8	package discoverycache
9	
10	import (
11		"context"
12		"errors"
13		"io/fs"
14		"os"
15		"path/filepath"
16		"strings"
17		"time"
18	
19		"golang.org/x/sync/singleflight"
20	)
21	
22	const (
23		lockAcquisitionTimeout = 100 * time.Millisecond
24		lockPollInterval       = 5 * time.Millisecond
25		waitPollInterval       = 250 * time.Millisecond
26		stalenessMultiplier    = time.Duration(2)
27	)
28	
29	// Cache is the root handle. Root is the base directory (e.g. ~/.cache/fizeau).
30	// Each Cache instance owns one in-process singleflight.Group; a new Cache per
31	// process is the normal usage.
32	type Cache struct {
33		Root string
34		sf   singleflight.Group
35	}
36	
37	// Source describes one cacheable data stream (one file under Root/Tier/Name.json).
38	type Source struct {
39		// Tier is "discovery" or "runtime".
40		Tier string
41		// Name is the kebab-case source identifier (e.g. "openrouter").
42		Name string
43		// TTL controls freshness: Read returns Fresh=true when Age < TTL.
44		TTL time.Duration
45		// RefreshDeadline is the maximum time a refresh is expected to take.
46		// Also controls the staleness threshold: 2 × RefreshDeadline.
47		RefreshDeadline time.Duration
48	}
49	
50	func (s Source) key() string { return s.Tier + "/" + s.Name }
51	
52	// ReadResult is the output of Cache.Read.
53	type ReadResult struct {
54		// Data is the raw bytes from the cache file; nil if no file exists.
55		Data []byte
56		// Age is how long ago the data was written (0 if absent).
57		Age time.Duration
58		// Fresh is true when Age < TTL and Data is non-nil.
59		Fresh bool
60		// Stale is true when Data is nil or Age >= TTL.
61		Stale bool
62	}
63	
64	// Refresher is the source-fetch function injected by the caller. The cache
65	// handles single-flight deduplication, the atomic write, and marker lifecycle.
66	type Refresher func(ctx context.Context) ([]byte, error)
67	
68	// Read returns cached data without any IO beyond reading the local file.
69	// It never blocks on network or PTY. If no cache file exists, Data is nil and
70	// Stale is true. Stale data is always returned without error; the caller
71	// decides whether to trigger a background refresh.
72	func (c *Cache) Read(s Source) (ReadResult, error) {
73		path := c.dataPath(s)
74		data, err := os.ReadFile(path) // #nosec G304
75		if errors.Is(err, os.ErrNotExist) {
76			return ReadResult{Stale: true}, nil
77		}
78		if err != nil {
79			return ReadResult{}, err
80		}
81		info, err := os.Stat(path)
82		if err != nil {
83			// File was just there; best-effort fallback.
84			return ReadResult{Data: data, Stale: true}, nil
85		}
86		age := time.Since(info.ModTime())
87		if age < 0 {
88			age = 0
89		}
90		fresh := age < s.TTL
91		return ReadResult{
92			Data:  data,
93			Age:   age,
94			Fresh: fresh,
95			Stale: !fresh,
96		}, nil
97	}
98	
99	// Prune removes data files (and their sidecar lock/marker/tmp files) for
100	// sources not listed in activeSources. Sources with an active .refreshing
101	// marker are skipped. Prune acquires the tier-1 lock before removing each
102	// source's files.
103	func (c *Cache) Prune(activeSources []Source) error {
104		active := make(map[string]bool, len(activeSources))
105		for _, s := range activeSources {
106			active[s.key()] = true
107		}
108	
109		return filepath.WalkDir(c.Root, func(path string, d fs.DirEntry, err error) error {
110			if err != nil || d.IsDir() {
111				return nil
112			}
113			if !strings.HasSuffix(d.Name(), ".json") {
114				return nil
115			}
116			rel, rerr := filepath.Rel(c.Root, path)
117			if rerr != nil {
118				return nil
119			}
120			parts := strings.SplitN(rel, string(filepath.Separator), 2)
121			if len(parts) != 2 {
122				return nil
123			}
124			tier := parts[0]
125			name := strings.TrimSuffix(parts[1], ".json")
126			if strings.ContainsRune(name, filepath.Separator) {
127				return nil // nested dir, skip
128			}
129	
130			if active[tier+"/"+name] {
131				return nil
132			}
133	
134			s := Source{Tier: tier, Name: name}
135	
136			// Skip sources with an active refresh in progress.
137			m, _ := readMarker(c.markerPath(s))
138			if isMarkerActiveForPrune(m) {
139				return nil
140			}
141	
142			release, lerr := c.acquireLock(s)
143			if lerr != nil {
144				return nil // can't lock; skip this source
145			}
146			defer release()
147	
148			// Re-check under lock.
149			m2, _ := readMarker(c.markerPath(s))
150			if isMarkerActiveForPrune(m2) {
151				return nil
152			}
153	
154			_ = os.Remove(c.dataPath(s))
155			_ = os.Remove(c.markerPath(s))
156			_ = os.Remove(c.tmpPath(s))
157			return nil
158		})
159	}
160	
161	// ---- internal ---------------------------------------------------------------
162	
163	type claimResult struct {
164		claimed bool
165		marker  *refreshMarker
166	}
167	
168	// claimRefresh implements Algorithm 1 from ADR-012. Must be called with the
169	// source directory already created (ensured by refreshAndCommit).
170	func (c *Cache) claimRefresh(s Source) (claimResult, error) {
171		release, err := c.acquireLock(s)
172		if err != nil {
173			return claimResult{}, err
174		}
175		defer release()
176	
177		existing, _ := readMarker(c.markerPath(s))
178		if existing != nil {
179			if isStale(s, existing) {
180				_ = os.Remove(c.markerPath(s))
181			} else {
182				return claimResult{claimed: false, marker: existing}, nil
183			}
184		}
185	
186		m := &refreshMarker{
187			PID:       os.Getpid(),
188			StartedAt: time.Now().UTC(),
189			Deadline:  time.Now().UTC().Add(s.RefreshDeadline),
190		}
191		if werr := writeMarker(c.markerPath(s), m); werr != nil {
192			return claimResult{}, werr
193		}
194		return claimResult{claimed: true}, nil
195	}
196	
197	// refreshAndCommit implements Algorithm 2 from ADR-012.
198	func (c *Cache) refreshAndCommit(s Source, fn Refresher) error {
199		if err := os.MkdirAll(filepath.Join(c.Root, s.Tier), 0o750); err != nil {
200			return err
201		}
202	
203		claim, err := c.claimRefresh(s)
204		if err != nil {
205			return err
206		}
207		if !claim.claimed {
208			// Another process is refreshing; wait for it.
209			return c.waitForRefresh(s, claim.marker)
210		}
211	
212		// We hold the claim. Run slow IO outside any lock.
213		data, fetchErr := fn(context.Background())
214		if fetchErr != nil {
215			c.releaseMarker(s)
216			return fetchErr
217		}
218	
219		if werr := atomicWrite(c.dataPath(s), data); werr != nil {
220			c.releaseMarker(s)
221			return werr
222		}
223	
224		c.releaseMarker(s)
225		return nil
226	}
227	
228	// waitForRefresh implements Algorithm 3 from ADR-012. Polls until the marker
229	// disappears or becomes stale, then returns (data has been written).
230	func (c *Cache) waitForRefresh(s Source, m *refreshMarker) error {
231		// Poll until deadline + staleness_threshold or s.RefreshDeadline, whichever first.
232		threshold := s.RefreshDeadline * stalenessMultiplier
233		absoluteDeadline := m.Deadline.Add(threshold)
234		maxWait := time.Now().Add(s.RefreshDeadline)
235		if maxWait.Before(absoluteDeadline) {
236			absoluteDeadline = maxWait
237		}
238	
239		for time.Now().Before(absoluteDeadline) {
240			time.Sleep(waitPollInterval)
241			current, _ := readMarker(c.markerPath(s))
242			if current == nil || isStale(s, current) {
243				return nil
244			}
245		}
246		return nil // timed out; caller will read whatever is on disk
247	}
248	
249	// releaseMarker removes the .refreshing marker under the tier-1 lock, but
250	// only if our PID is still recorded (guard against PID-reuse races, per §2
251	// of refreshAndCommit pseudocode in ADR-012).
252	func (c *Cache) releaseMarker(s Source) {
253		release, err := c.acquireLock(s)
254		if err != nil {
255			return
256		}
257		defer release()
258		m, _ := readMarker(c.markerPath(s))
259		if m != nil && m.PID == os.Getpid() {
260			_ = os.Remove(c.markerPath(s))
261		}
262	}
263	
264	// ---- path helpers -----------------------------------------------------------
265	
266	func (c *Cache) dataPath(s Source) string {
267		return filepath.Join(c.Root, s.Tier, s.Name+".json")
268	}
269	
270	func (c *Cache) lockPath(s Source) string {
271		return filepath.Join(c.Root, s.Tier, s.Name+".lock")
272	}
273	
274	func (c *Cache) markerPath(s Source) string {
275		return filepath.Join(c.Root, s.Tier, s.Name+".refreshing")
276	}
277	
278	func (c *Cache) tmpPath(s Source) string {
279		return filepath.Join(c.Root, s.Tier, s.Name+".json.tmp")
280	}
