1	// Package quotaheaders parses provider-supplied rate-limit / quota response
2	// headers into a structured Signal. The Signal feeds the per-provider quota
3	// state machine introduced in fizeau-92b4b823 so dispatch can route around
4	// providers whose subscription/daily cap is hit (or imminently will be).
5	//
6	// This package is intentionally limited to the subscription/daily exhaustion
7	// case. Per-second / per-minute throttling (a 429 with a short Retry-After)
8	// stays in the per-request feedback path.
9	package quotaheaders
10	
11	import (
12		"net/http"
13		"strconv"
14		"strings"
15		"time"
16	)
17	
18	// Signal is the structured shape returned by every per-provider parser.
19	// All fields are zero values when the corresponding header is missing.
20	//
21	// The router treats a Signal as actionable only when Present is true; that
22	// guards against treating a response with no rate-limit headers (e.g. a
23	// 200 from a self-hosted endpoint) as "remaining tokens = 0".
24	type Signal struct {
25		// Present is true when the response carried at least one recognized
26		// rate-limit header. Consumers must check Present before reading the
27		// numeric fields.
28		Present bool
29	
30		// RemainingTokens is the remaining token budget in the current window.
31		// -1 means the provider did not report a token budget on this response.
32		RemainingTokens int64
33		// RemainingRequests is the remaining request budget in the current
34		// window. -1 means the provider did not report a request budget.
35		RemainingRequests int64
36	
37		// ResetTime is the absolute wall-clock instant when the smaller of the
38		// remaining-tokens / remaining-requests window resets. Zero when no
39		// reset header was supplied.
40		ResetTime time.Time
41	
42		// RetryAfter is the duration carried by an explicit Retry-After header.
43		// Zero when absent. RetryAfter > 0 always indicates the provider has
44		// already returned a 429-class response and wants the caller to wait.
45		RetryAfter time.Duration
46	}
47	
48	// retryAfterTime returns the wall-clock instant the provider wants the caller
49	// to retry after, or zero when neither RetryAfter nor ResetTime are set.
50	// RetryAfter takes precedence because it is always provider-authoritative;
51	// ResetTime is the fall-back when only the reset window is exposed.
52	func (s Signal) retryAfterTime(now time.Time) time.Time {
53		if s.RetryAfter > 0 {
54			return now.Add(s.RetryAfter)
55		}
56		return s.ResetTime
57	}
58	
59	// IsExhausted applies the conservative "remaining tokens/requests would not
60	// last to the next reset" heuristic from the bead. The current rule:
61	//
62	//   - explicit Retry-After > 0 (provider already returned 429) — exhausted
63	//   - RemainingRequests reported and == 0 — exhausted
64	//   - RemainingTokens reported and == 0 — exhausted
65	//
66	// Returns the wall-clock retry-after time (zero when nothing actionable was
67	// signaled). The "will-exhaust-before-reset" predicate is intentionally
68	// conservative: only zero-budget triggers exhaustion. That keeps false
69	// positives out of the dispatch path while still catching the cases where
70	// the provider has authoritatively said "no more headroom in this window."
71	func (s Signal) IsExhausted(now time.Time) (bool, time.Time) {
72		if !s.Present {
73			return false, time.Time{}
74		}
75		if s.RetryAfter > 0 {
76			return true, s.retryAfterTime(now)
77		}
78		if s.RemainingRequests == 0 || s.RemainingTokens == 0 {
79			// "0" only counts when the header was actually present. The
80			// parsers use -1 for "not reported" so a missing header does
81			// not look like exhaustion.
82			return true, s.retryAfterTime(now)
83		}
84		return false, time.Time{}
85	}
86	
87	// ParseAnthropic decodes Anthropic Messages-API rate-limit headers.
88	//
89	// Recognized canonical headers (current Anthropic docs):
90	//
91	//	anthropic-ratelimit-requests-{limit,remaining,reset}
92	//	anthropic-ratelimit-tokens-{limit,remaining,reset}
93	//	anthropic-ratelimit-input-tokens-{limit,remaining,reset}
94	//	anthropic-ratelimit-output-tokens-{limit,remaining,reset}
95	//	retry-after
96	//
97	// The bead also references the legacy "X-RateLimit-Remaining-*" family;
98	// those names are accepted for forward-compatibility but the canonical
99	// "anthropic-ratelimit-*" names are preferred when both are present.
100	//
101	// Reset values are RFC3339 timestamps (Anthropic) and are returned as the
102	// minimum of the per-axis reset times so the consumer wakes at the earliest
103	// recovery boundary.
104	func ParseAnthropic(h http.Header, now time.Time) Signal {
105		if h == nil {
106			return Signal{RemainingTokens: -1, RemainingRequests: -1}
107		}
108		sig := Signal{RemainingTokens: -1, RemainingRequests: -1}
109	
110		requestsRem, requestsRemOK := readInt(h, "anthropic-ratelimit-requests-remaining", "x-ratelimit-remaining-requests")
111		if requestsRemOK {
112			sig.Present = true
113			sig.RemainingRequests = requestsRem
114		}
115	
116		// Anthropic exposes total-tokens, plus per-axis input/output budgets.
117		// Track the smallest reported "remaining tokens" since the smallest
118		// budget is the binding one for the next request.
119		tokenAxes := []string{
120			"anthropic-ratelimit-tokens-remaining",
121			"anthropic-ratelimit-input-tokens-remaining",
122			"anthropic-ratelimit-output-tokens-remaining",
123			"x-ratelimit-remaining-tokens",
124		}
125		for _, name := range tokenAxes {
126			v, ok := readInt(h, name)
127			if !ok {
128				continue
129			}
130			sig.Present = true
131			if sig.RemainingTokens < 0 || v < sig.RemainingTokens {
132				sig.RemainingTokens = v
133			}
134		}
135	
136		resetAxes := []string{
137			"anthropic-ratelimit-requests-reset",
138			"anthropic-ratelimit-tokens-reset",
139			"anthropic-ratelimit-input-tokens-reset",
140			"anthropic-ratelimit-output-tokens-reset",
141		}
142		for _, name := range resetAxes {
143			raw := strings.TrimSpace(h.Get(name))
144			if raw == "" {
145				continue
146			}
147			t, err := time.Parse(time.RFC3339, raw)
148			if err != nil {
149				continue
150			}
151			sig.Present = true
152			if sig.ResetTime.IsZero() || t.Before(sig.ResetTime) {
153				sig.ResetTime = t
154			}
155		}
156	
157		if d, ok := readRetryAfter(h, now); ok {
158			sig.Present = true
159			sig.RetryAfter = d
160		}
161	
162		return sig
163	}
164	
165	// ParseOpenAI decodes OpenAI Chat Completions rate-limit headers.
166	//
167	// Recognized headers (https://platform.openai.com/docs/guides/rate-limits):
168	//
169	//	x-ratelimit-limit-requests
170	//	x-ratelimit-limit-tokens
171	//	x-ratelimit-remaining-requests
172	//	x-ratelimit-remaining-tokens
173	//	x-ratelimit-reset-requests   (duration: "1s", "100ms", "2m30s")
174	//	x-ratelimit-reset-tokens     (duration)
175	//	retry-after
176	//
177	// Reset values are durations; this parser converts them to absolute times
178	// using `now`.
179	func ParseOpenAI(h http.Header, now time.Time) Signal {
180		if h == nil {
181			return Signal{RemainingTokens: -1, RemainingRequests: -1}
182		}
183		sig := Signal{RemainingTokens: -1, RemainingRequests: -1}
184	
185		if v, ok := readInt(h, "x-ratelimit-remaining-requests"); ok {
186			sig.Present = true
187			sig.RemainingRequests = v
188		}
189		if v, ok := readInt(h, "x-ratelimit-remaining-tokens"); ok {
190			sig.Present = true
191			sig.RemainingTokens = v
192		}
193	
194		for _, name := range []string{"x-ratelimit-reset-requests", "x-ratelimit-reset-tokens"} {
195			raw := strings.TrimSpace(h.Get(name))
196			if raw == "" {
197				continue
198			}
199			d, err := parseOpenAIDuration(raw)
200			if err != nil {
201				continue
202			}
203			sig.Present = true
204			t := now.Add(d)
205			if sig.ResetTime.IsZero() || t.Before(sig.ResetTime) {
206				sig.ResetTime = t
207			}
208		}
209	
210		if d, ok := readRetryAfter(h, now); ok {
211			sig.Present = true
212			sig.RetryAfter = d
213		}
214	
215		return sig
216	}
217	
218	// ParseOpenRouter decodes OpenRouter rate-limit headers.
219	//
220	// Recognized headers (https://openrouter.ai/docs/limits):
221	//
222	//	x-ratelimit-limit
223	//	x-ratelimit-remaining
224	//	x-ratelimit-reset    (Unix ms timestamp)
225	//	retry-after
226	//
227	// OpenRouter expresses one combined budget rather than separate token /
228	// request axes; the parser maps it onto RemainingRequests and leaves
229	// RemainingTokens at -1 ("not reported").
230	func ParseOpenRouter(h http.Header, now time.Time) Signal {
231		if h == nil {
232			return Signal{RemainingTokens: -1, RemainingRequests: -1}
233		}
234		sig := Signal{RemainingTokens: -1, RemainingRequests: -1}
235	
236		if v, ok := readInt(h, "x-ratelimit-remaining"); ok {
237			sig.Present = true
238			sig.RemainingRequests = v
239		}
240	
241		if raw := strings.TrimSpace(h.Get("x-ratelimit-reset")); raw != "" {
242			if ms, err := strconv.ParseInt(raw, 10, 64); err == nil && ms > 0 {
243				sig.Present = true
244				sig.ResetTime = time.UnixMilli(ms).UTC()
245			}
246		}
247	
248		if d, ok := readRetryAfter(h, now); ok {
249			sig.Present = true
250			sig.RetryAfter = d
251		}
252	
253		return sig
254	}
255	
256	// readInt looks up the first non-empty header value in `names` and parses it
257	// as a 64-bit integer. The "ok" return distinguishes "header absent" from
258	// "header present and zero" — important for IsExhausted, which treats a
259	// reported zero as exhaustion but a missing header as no signal.
260	func readInt(h http.Header, names ...string) (int64, bool) {
261		for _, name := range names {
262			raw := strings.TrimSpace(h.Get(name))
263			if raw == "" {
264				continue
265			}
266			v, err := strconv.ParseInt(raw, 10, 64)
267			if err != nil {
268				continue
269			}
270			return v, true
271		}
272		return 0, false
273	}
274	
275	// readRetryAfter parses an HTTP Retry-After header into a positive duration.
276	// Per RFC 7231 §7.1.3 the value is either delta-seconds or an HTTP-date.
277	func readRetryAfter(h http.Header, now time.Time) (time.Duration, bool) {
278		raw := strings.TrimSpace(h.Get("retry-after"))
279		if raw == "" {
280			return 0, false
281		}
282		if secs, err := strconv.ParseInt(raw, 10, 64); err == nil {
283			if secs <= 0 {
284				return 0, false
285			}
286			return time.Duration(secs) * time.Second, true
287		}
288		if t, err := http.ParseTime(raw); err == nil {
289			d := t.Sub(now)
290			if d <= 0 {
291				return 0, false
292			}
293			return d, true
294		}
295		return 0, false
296	}
297	
298	// parseOpenAIDuration parses the OpenAI compound-duration form ("2m30s",
299	// "100ms", "1s") into a time.Duration. time.ParseDuration handles every
300	// shape OpenAI emits today; this wrapper exists so tests can reach the same
301	// helper directly when verifying edge cases.
302	func parseOpenAIDuration(raw string) (time.Duration, error) {
303		return time.ParseDuration(raw)
304	}
