func TestCollect_LatencyRecorded(t *testing.T) {
	store := runtimesignals.NewStore()

	for _, d := range []time.Duration{10, 20, 30} {
		store.RecordResponse("latency-test", nil, d*time.Millisecond, "openai")
	}

